/// <summary>
/// This class handles the dialog for modification of Excise Register Entry records
/// </summary>
class METExciseRegisterEntryModifyDialog
{
    protected Dialog        dialog;
    protected DialogField   dlgLodgement, dlgReceiptQty, dlgPermisionNumber, dlgTIUV, dlgReasonCode, dlgDeleteRecord, dlgWUVCase;

    private METLodgement                metLodgement;
    private METReceiptQuantity          receiptQty;
    private METPermissionNumber         permissionNumber;
    private METTransportInsurance       tiuv;
    private ReasonComment               reasonCode;
    private METDutyRateReceived         wuvCase;
    private NoYesId                     deleteRecord;
    
}

Method.Source:
    /// <summary>
    /// Entry point method of the operation
    /// </summary>
    /// <param name = "_args">Args</param>
    public static void main(Args _args)
    {
        METExciseRegisterEntryModifyDialog  dialogExciseRegisterEntry;
        METExciseRegisterEntry              metExciseRegisterEntry;

        //Check if the Args.Record() has the same TableID as the Table Buffer(custTable).
        if  (_args.record().TableId == tableNum(METExciseRegisterEntry))
        {
            //Assign the args records to table buffer and then pass it to salesLine_ds(FormDataSource)
            metExciseRegisterEntry      = _args.record();
 
            //Call Method which will be used to create the Dialog
            dialogExciseRegisterEntry = new METExciseRegisterEntryModifyDialog();
            dialogExciseRegisterEntry.updateExciseRegisterEntries(metExciseRegisterEntry);

            FormDataSource metExciseRegisterEntry_ds   = FormDataUtil::getFormDataSource(metExciseRegisterEntry);  //metExciseRegisterEntry.dataSource();
            metExciseRegisterEntry_ds.executeQuery();
        }
    }

    /// <summary>
    /// Updates the excise register entries incoming from Args.
    /// </summary>
    /// <param name = "metExciseRegisterEntry">Table buffer of <c>METExciseRegisterEntry</c></param>
    private void updateExciseRegisterEntries(METExciseRegisterEntry metExciseRegisterEntry)
    {
        dialog = this.dialog(metExciseRegisterEntry);

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            if(this.getFromDialog())
            {   
                METLodgement lodgementOld = metExciseRegisterEntry.Lodgement;
                this.updateRegisterAndCreateLog(metExciseRegisterEntry, true);
                
                if(lodgementOld != metLodgement)
                {
                    this.updateOtherTransForLodgementUpdate(lodgementOld, metExciseRegisterEntry.Site, metExciseRegisterEntry.ItemId);
                }
            }
        }
    }

    /// <summary>
    /// Updates the excise register entries for purchase and sales.
    /// </summary>
    /// <param name = "metExciseRegisterEntry">Table buffer of <c>METExciseRegisterEntry</c></param>
    /// <param name = "_isPurchLine">Indicates whether the register entry is from purchase or sales</param>
    private void updateRegisterAndCreateLog(METExciseRegisterEntry _exciseRegisterEntry, boolean _isPurchLine)
    {
        try
        {
            ttsbegin;

            //only modify if available Qty matches quantity i.e nothing has been consumed
            METExciseRegisterEntryUpdateLog     updateLog;
            updateLog.Site                              = _exciseRegisterEntry.Site;
            updateLog.ItemId                            = _exciseRegisterEntry.ItemId;
            updateLog.OriginNumber                      = _exciseRegisterEntry.OriginNumber;
            updateLog.METExciseRegisterEntryRefRecId    = _exciseRegisterEntry.RecId;
            updateLog.ReasonCode                        = reasonCode;
                
            _exciseRegisterEntry.selectForUpdate(true);

            if(_isPurchLine && deleteRecord)
            {
                updateLog.ChangeType            = VersioningChangeType::Deleted;
                updateLog.LodgementOld          = _exciseRegisterEntry.Lodgement;
                updateLog.PermissionNumberOld   = _exciseRegisterEntry.PermissionNumber;
                updateLog.ReceiptQuantityOld    = _exciseRegisterEntry.Quantity;
                updateLog.TIUVOld               = _exciseRegisterEntry.TIUV;
                updateLog.DutyRateReceivedOld   = _exciseRegisterEntry.DutyRateReceived;

                _exciseRegisterEntry.delete();
            }
            else
            {
                updateLog.ChangeType = VersioningChangeType::Updated;

                if(_exciseRegisterEntry.Lodgement != metLodgement)
                {
                    updateLog.LodgementOld = _exciseRegisterEntry.Lodgement;
                    updateLog.LodgementNew = metLodgement;

                    _exciseRegisterEntry.Lodgement = metLodgement;
                }

                if(_isPurchLine && _exciseRegisterEntry.PermissionNumber != permissionNumber)
                {
                    updateLog.PermissionNumberOld = _exciseRegisterEntry.PermissionNumber;
                    updateLog.PermissionNumberNew = permissionNumber;

                    _exciseRegisterEntry.PermissionNumber = permissionNumber;
                }

                if(_isPurchLine && _exciseRegisterEntry.Quantity != receiptQty)
                {
                    updateLog.ReceiptQuantityOld = _exciseRegisterEntry.Quantity;
                    updatelog.ReceiptQuantityNew = receiptQty;

                    _exciseRegisterEntry.ReceiptQuantity = receiptQty;
                    _exciseRegisterEntry.updateQtyAndDuty();
                }

                if(_isPurchLine && _exciseRegisterEntry.TIUV != tiuv)
                {
                    updateLog.TIUVOld = _exciseRegisterEntry.TIUV;
                    updateLog.TIUVNew = tiuv;

                    _exciseRegisterEntry.TIUV = tiuv;
                }

                if(_isPurchLine && _exciseRegisterEntry.DutyRateReceived != wuvCase && _exciseRegisterEntry.Quantity != 0)
                {
                    updateLog.DutyRateReceivedOld = _exciseRegisterEntry.DutyRateReceived;
                    updatelog.DutyRateReceivedNew = wuvCase;

                    _exciseRegisterEntry.DutyRateReceived = wuvCase;
                    //calculate duty rate received per unit in inventory unit (to be used by other type of entries)
                    _exciseRegisterEntry.CustomValue                = _exciseRegisterEntry.DutyRateReceived * _exciseRegisterEntry.ReceiptQuantity;
                    _exciseRegisterEntry.DutyRateReceivedInventUnit = _exciseRegisterEntry.CustomValue / _exciseRegisterEntry.Quantity;

                    _exciseRegisterEntry.calculateTotalDuty();
                            
                }
                _exciseRegisterEntry.update();
            }

            updateLog.insert();
            ttscommit;
            info(StrFmt("@MET:ChangesHaveBeenUpdatedForOriginNumberDashP1ItemidDashP2", _exciseRegisterEntry.OriginNumber, _exciseRegisterEntry.ItemId));
        }
        catch
        {
            error("@MET:UnexpectedErrorPleaseTryAgainOrContactSystemAdmin");
        }
    }

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <param name = "metExciseRegisterEntry">table record used to set initial values</param>
    /// <returns>The dialog</returns>
    protected Dialog dialog(metExciseRegisterEntry metExciseRegisterEntry)
    {
        //Create a Dialog with title
        dialog = new Dialog("@MET:ModifyExciseRegisterEntries");

        dlgDeleteRecord    = dialog.addField(ExtendedTypeStr(NoYesId),"@MET:CancelRecord");
        dlgDeleteRecord.value(strFmt("@MET:P1",NoYes::No));
        //Override modified method for dlgDeleteRecord
        dlgDeleteRecord.registerOverrideMethod(methodStr(FormStringControl, modified), methodStr(METExciseRegisterEntryModifyDialog, dialogDeleteRecord_modified), this);

        dlgLodgement        = dialog.addField(extendedTypeStr(METLodgement),"@MET:LodgementId");
        dlgLodgement.value(strFmt("@MET:P1",metExciseRegisterEntry.Lodgement));

        dlgPermisionNumber = dialog.addField(extendedTypeStr(METPermissionNumber),"@MET:PermissionNumber");
        dlgPermisionNumber.value(strFmt("@MET:P1",metExciseRegisterEntry.PermissionNumber));

        dlgReceiptQty   = dialog.addField(extendedTypeStr(Qty),"@SYS14578");
        dlgReceiptQty.value(strFmt("@MET:P1",metExciseRegisterEntry.ReceiptQuantity));
        dlgReceiptQty.allowEdit(metExciseRegisterEntry.ReceiptQuantity == metExciseRegisterEntry.AvailableQuantity);


        dlgTIUV            = dialog.addField(extendedTypeStr(METTransportInsurance),"@MET:TIUV");
        dlgTIUV.value(strFmt("@MET:P1",metExciseRegisterEntry.TIUV));

        dlgWUVCase         = dialog.addField(extendedTypeStr(METDutyRateReceived),"@MET:WUVUnit");
        dlgWUVCase.value(strFmt("@MET:P1",metExciseRegisterEntry.DutyRateReceived));
        dlgWUVCase.allowEdit(metExciseRegisterEntry.CustomsExcise == METCustomExcise::C);
        

        dlgReasonCode      = dialog.addField(extendedTypeStr(ReasonComment),"@MET:ReasonCode");
        dlgReasonCode.fieldControl().mandatory(true);

        //Create a "Label" do Dialog
        dialog.addText("@MET:DoYouWishToProceed");

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// disable controls on Dialog form if record need to be deleted
    /// </summary>
    /// <param name = "_dlgDeleteRecord">delete record dialog control</param>
    /// <returns>alwyas true</returns>
    private boolean dialogDeleteRecord_modified(FormCheckBoxControl _dlgDeleteRecord)
    {
        if (_dlgDeleteRecord.value() == true)
        {
            dlgLodgement.enabled(false);
            dlgPermisionNumber.enabled(false);
            dlgReceiptQty.enabled(false);
            dlgTIUV.enabled(false);
            dlgWUVCase.enabled(false);
        }
        else
        {
            dlgLodgement.enabled(true);
            dlgPermisionNumber.enabled(true);
            dlgReceiptQty.enabled(true);
            dlgTIUV.enabled(true);
            dlgWUVCase.enabled(true);
        }

        return true;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        deleteRecord        = dlgDeleteRecord.value();
        metLodgement        = dlgLodgement.value();
        receiptQty          = dlgReceiptQty.value();
        permissionNumber    = dlgPermisionNumber.value();
        tiuv                = dlgTIUV.value();
        reasonCode          = dlgReasonCode.value();
        wuvCase             = dlgWUVCase.value();

        //do any validation here
        if(deleteRecord == NoYes::No && metLodgement == '')
        {
            ret = checkFailed("@MET:LodgementNumberIsMandatory");
        }

        return ret;
    }

/// <summary>
/// Gets and initiate update of lodgement for sales excise register entries
/// </summary>
/// <param name = "_lodgementOld">Old lodgement number</param>
/// <param name = "_siteId">Site id</param>
/// <param name = "_itemId">Item id</param>
private void updateOtherTransForLodgementUpdate(METLodgement _lodgementOld, InventSiteId _siteId, ItemId _itemId)
{
    METExciseRegisterEntry exciseRegisterEntrySales;
    
    while select 
        forupdate   exciseRegisterEntrySales
        where       exciseRegisterEntrySales.Lodgement  == _lodgementOld
        &&          exciseRegisterEntrySales.ItemId     == _itemId
        &&          exciseRegisterEntrySales.OriginType != METOriginType::PurchaseOrder
    {
        this.updateRegisterAndCreateLog(exciseRegisterEntrySales, false);
    }
}

/// <summary>
/// Construct and return the class object
/// </summary>
/// <returns>class object</returns>
public static METExciseRegisterEntryModifyDialog construct()
{
    return new METExciseRegisterEntryModifyDialog();
}

/// <summary>
/// Protected constructor method
/// </summary>
protected void new()
{
}
